@font-face {
	font-family: Seal Sans base64;
	src:
		url(data:font/woff2;charset=utf-8;base64,) format(woff2);
	font-style: normal;
	font-weight: normal;
	font-width: normal;
	unicode-range: U+3D000-3FC3F;
	font-display: swap;
	font-language-override: normal;
	ascent-override: 50%;
	descent-override: 50%;
	line-gap-override: 0%;
}
